<?php $p=$data['professional']; if(!$p): ?><div class="empty-state"><h1>Coiffeur introuvable</h1></div><?php else: ?><section class="booking-page reveal"><div class="back-row"><a href="<?= APP_URL ?>/index.php?page=professional&id=<?= (int)$p['id'] ?>">←</a><span>Créer un rendez-vous</span></div><div class="booking-head"><img src="<?= APP_URL.'/'.e($p['photo_path']) ?>" alt=""><div><h1>Choisir ton créneau</h1><p><?= e($p['full_name']) ?> · <?= e($p['zone']) ?></p></div></div><form method="post" class="booking-form" id="bookingForm"><?= csrf_field() ?><input type="hidden" name="action" value="create_booking"><input type="hidden" name="professional_id" value="<?= (int)$p['id'] ?>"><label>Prestation<select name="service_id" required><?php foreach($data['services'] as $s): ?><option value="<?= (int)$s['id'] ?>"><?= e($s['name']) ?> — <?= number_format((float)$s['price'],0,' ',' ') ?> FCFA</option><?php endforeach; ?></select></label><label>Date<input type="date" name="date" min="<?= date('Y-m-d') ?>" required></label><label>Heure<div class="time-grid"><?php foreach(['09:00','10:00','11:30','13:00','14:00','15:00','16:00','17:30','18:30'] as $t): ?><button type="button" class="time-chip" data-time="<?= $t ?>"><?= $t ?></button><?php endforeach; ?></div><input type="hidden" name="time" id="timeInput" required></label><label>Mode<select name="mode"><option>Au salon</option><option>Chez le client</option></select></label><label>Quartier / zone<input name="zone" value="<?= e($p['zone']) ?>" required></label><div class="summary-mini"><span>Total estimé</span><strong id="pricePreview">Sélectionne une prestation</strong></div><button class="primary-btn full" type="submit">Confirmer le rendez-vous <span>→</span></button><p class="fineprint">L'adresse exacte reste privée jusqu'à la confirmation. Le serveur vérifie aussi le créneau pour éviter une double réservation.</p></form></section><?php endif; ?>
